# Improve authored prose spacing only. Never transform a preserved original/question.
def smooth(text):
 text=re.sub(r'\b(up to|within|at most|at least|no more than|over|under|actual|printed|one|only|rank|ranks|level|class level|base|Speed|HP|AC|RP|RC)(?=\d)',r'\1 ',text)
 text=re.sub(r'(?<=\d)(?=(?:ft³|ft²|ft|lb|HP|RP|RC|AC|hours?|minutes?|seconds?|rounds?|feet|inches?|targets?|uses?|points?|fire|psychic|necrotic|slashing|piercing|bludgeoning)\b)',' ',text)
 return text
for _p in policies:_p['wording']=smooth(_p['wording'])
for _d in decisions.values():
 if _d['authoring']:
  for _k,_v in list(_d['authoring'].items()):
   if isinstance(_v,str):_d['authoring'][_k]=smooth(_v)
 _d['explicitConflictDispositions']=[smooth(s) for s in _d['explicitConflictDispositions']]
 _d['particularOperationPrerequisites']=[smooth(s) for s in _d['particularOperationPrerequisites']]
 if 'workedBoundary' in _d:_d['workedBoundary']['wording']=smooth(_d['workedBoundary']['wording'])

def writej(name,value):
 p=O/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False)+'\n');return p

def writet(name,value):
 p=O/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value.rstrip()+'\n');return p

